package dev.aiphone.diagnostics;
import android.app.Activity;import android.os.Bundle;import android.view.*;import android.widget.*;import android.text.*;import android.hardware.*;import org.json.*;import java.io.*;
public final class GestureProof extends Activity implements SensorEventListener {
 int maxPointers=0,moves=0,ups=0,downs=0;float firstX=-1,firstY=-1,lastX=0,lastY=0,maxAcceleration=0,maxPressure=0;String text="";SensorManager sensors;
 void save(){try{JSONObject j=new JSONObject();j.put("maxPointers",maxPointers);j.put("moves",moves);j.put("ups",ups);j.put("downs",downs);j.put("firstX",firstX);j.put("firstY",firstY);j.put("lastX",lastX);j.put("lastY",lastY);j.put("maxAcceleration",maxAcceleration);j.put("maxPressure",maxPressure);j.put("text",text);try(FileOutputStream f=openFileOutput("gesture.json",MODE_PRIVATE)){f.write(j.toString().getBytes("UTF-8"));}}catch(Exception e){throw new RuntimeException(e);}}
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setFlags(1024,1024);getWindow().getDecorView().setSystemUiVisibility(5894);LinearLayout layout=new LinearLayout(this);layout.setOrientation(1);layout.setPadding(32,32,32,32);TextView title=new TextView(this);title.setText("手势校验");title.setTextSize(22);layout.addView(title);EditText input=new EditText(this);input.setHint("中文输入校验");input.setSingleLine(false);layout.addView(input,new LinearLayout.LayoutParams(-1,160));input.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int b,int c){text=s.toString();save();}public void afterTextChanged(Editable e){}});View canvas=new View(this);canvas.setBackgroundColor(0xffe5edf5);layout.addView(canvas,new LinearLayout.LayoutParams(-1,-1));canvas.setOnTouchListener((v,e)->true);setContentView(layout);sensors=(SensorManager)getSystemService(SENSOR_SERVICE);sensors.registerListener(this,sensors.getDefaultSensor(Sensor.TYPE_ACCELEROMETER),SensorManager.SENSOR_DELAY_GAME);save();}
 @Override public boolean dispatchTouchEvent(MotionEvent e){maxPointers=Math.max(maxPointers,e.getPointerCount());int a=e.getActionMasked();if(a==MotionEvent.ACTION_DOWN){downs++;if(firstX<0){firstX=e.getRawX();firstY=e.getRawY();}}if(a==MotionEvent.ACTION_MOVE)moves++;if(a==MotionEvent.ACTION_UP)ups++;lastX=e.getRawX();lastY=e.getRawY();maxPressure=Math.max(maxPressure,e.getPressure());save();return super.dispatchTouchEvent(e);}
 public void onSensorChanged(SensorEvent e){maxAcceleration=Math.max(maxAcceleration,Math.abs(e.values[0]));save();}public void onAccuracyChanged(Sensor s,int a){}@Override public void onDestroy(){if(sensors!=null)sensors.unregisterListener(this);super.onDestroy();}
}
